    Finds all starting indices where the pattern is found in the text.
    """
    occurrences: list[int] = []
    text_length: int = len(text)
    pattern_length: int = len(pattern)

    if pattern_length == 0:
        return list(range(text_length + 1))

    if text_length < pattern_length:
        return occurrences

    for i in range(text_length - pattern_length + 1):
        current_slice: str = text[i : i + pattern_length]
        if current_slice == pattern:
            occurrences.append(i)

    return occurrences

def main() -> None:
    test_cases: list[tuple[str, str, list[int]]] = [
        ('ababab', 'aba', [0, 2]),
        ('hello world', 'o', [4, 7]),
        ('aaaaa', 'aa', [0, 1, 2, 3]),
        ('abcde', 'xyz', []),
        ('single', 'single', [0]),
        ('empty pattern', '', list(range(14))),
        ('', 'pattern', []),
        ('testtest', 'test', [0, 4]),
    ]

    for text, pattern, expected in test_cases:
        result: list[int] = find_all_occurrences(text, pattern)
        assert result == expected, f"Text: '{text}', Pattern: '{pattern}', Expected: {expected}, Got: {result}"
        print(f"Test passed for '{text}' and '{pattern}'. Result: {result}")

if __name__ == "__main__":
    main()

