def extract_digits(text: str) -> str:
    """
    Extracts all digits from a given string and returns them as a new string.
    """
    digit_chars: list[str] = []
    for char in text:
        if '0' <= char <= '9':
            digit_chars.append(char)
    return "".join(digit_chars)

def process_multiple_texts(texts: list[str]) -> dict[str, str]:
    """
    Processes a list of strings, extracting digits from each and returning
    a dictionary mapping original text to extracted digits.
    """
    results: dict[str, str] = {}
    for item in texts:
        extracted: str = extract_digits(item)
        results[item] = extracted
    return results

def count_digit_occurrences(extracted_texts: list[str]) -> dict[str, int]:
    """
    Counts the occurrences of each digit across a list of strings containing only digits.
    """
    digit_counts: dict[str, int] = {str(i): 0 for i in range(10)}
    for text_with_digits in extracted_texts:
        for digit in text_with_digits:
            if digit in digit_counts:
                digit_counts[digit] += 1
    return digit_counts

