def has_unmet_dependencies(task_name: str,
                           tasks: list[dict[str, object]],
                           completed_tasks: list[str]) -> bool:

    task_map: dict[str, dict[str, object]] = {task['name']: task for task in tasks}

    if task_name not in task_map:
        return False 

    current_task: dict[str, object] = task_map[task_name]

    dependencies: list[str] = current_task.get('dependencies', [])

    completed_set: set[str] = set(completed_tasks)

    for dep_name in dependencies:
        if dep_name not in completed_set:
            return True

    return False

