import math

def prime_factors(n: int) -> list[int]:
    factors: list[int] = []
    d: int = 2
    temp_n: int = n

    while d * d <= temp_n:
        while temp_n % d == 0:
            factors.append(d)
            temp_n //= d
        d += 1

    if temp_n > 1:
        factors.append(temp_n)

    return factors

