def parse_args(args_list: list[str]) -> dict[str, str | bool]:
    parsed_args: dict[str, str | bool] = {}
    i: int = 0
    list_len: int = len(args_list)

    while i < list_len:
        arg: str = args_list[i]
        if arg.startswith('--'):
            key: str = arg[2:]
            if i + 1 < list_len and not args_list[i + 1].startswith('--'):
                value: str = args_list[i + 1]
                parsed_args[key] = value
                i += 2
            else:
                parsed_args[key] = True
                i += 1
        else:
            i += 1
    return parsed_args

def example_usage() -> None:
    example1_args: list[str] = ['--name', 'John', '--age', '30', '--verbose']
    result1: dict[str, str | bool] = parse_args(example1_args)
