    example2_args: list[str] = ['--file', 'data.txt']
    result2: dict[str, str | bool] = parse_args(example2_args)
    print(f"Result 2: {result2}")

    example3_args: list[str] = ['--debug', '--log', 'app.log']
    result3: dict[str, str | bool] = parse_args(example3_args)
    print(f"Result 3: {result3}")

