def swap_dict_keys_values(original_dict: dict[str, int]) -> dict[int, str]:
    """
    Swaps the keys and values of a dictionary.
    Assumes all values are hashable and unique.

    Args:
        original_dict: The input dictionary.

    Returns:
        A new dictionary with keys and values swapped.
    """
    swapped_dict: dict[int, str] = {}
    for key, value in original_dict.items():
        swapped_dict[value] = key
    return swapped_dict

def main() -> None:
    dict1: dict[str, int] = {'a': 1, 'b': 2}
    result1: dict[int, str] = swap_dict_keys_values(dict1)
    print(f"Original: {dict1}, Swapped: {result1}")

    dict2: dict[str, str] = {'name': 'Alice'}
    result2: dict[str, str] = swap_dict_keys_values(dict2) # type: ignore
    print(f"Original: {dict2}, Swapped: {result2}")

    dict3: dict[str, bool] = {'is_true': True, 'is_false': False}
    result3: dict[bool, str] = swap_dict_keys_values(dict3) # type: ignore
    print(f"Original: {dict3}, Swapped: {result3}")

if __name__ == '__main__':
    main()

