def filter_dict_by_value_range(data_dict: dict[str, int | float], min_val: int | float, max_val: int | float) -> dict[str, int | float]:
    """
    Filters a dictionary, keeping only key-value pairs where the value
    falls within a specified inclusive range [min_val, max_val].
    """
    filtered_data: dict[str, int | float] = {}
    for key, value in data_dict.items():
        if min_val <= value <= max_val:
            filtered_data[key] = value
    return filtered_data

